INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64031977', 64031977, 'analyze_legacy', 'Kab. Hulu Sungai Tengah', 'kabkota', 'Dinas Kesehatan', 'Belanja Makanan dan Minuman Pemberdayaan kader dalam rangka pencegahan dan pengendalian penyakit menular dan penyakit tidak menular, pelaksanaan imunisasi (Birayang)', 'Barang', 'Pengadaan Langsung', 'Kalimantan Selatan, Hulu Sungai Tengah (Kab.)', 6390000, 'January 2026', 'APBD', 1, 1, '1 Paket', '-Pemberdayaan kader dalam rangka pencegahan dan pengendalian penyakit menular -Pemberdayaan kader dalam rangka pencegahan dan pengendalian penyakit tidak menular -Pemberdayaan kader masyarakat terlibat dalam pelaksanaan imunisasi dan surveilans PD3I -Pemicuan pilar 1 s/d 5 STBM kepada Masyarakat dan Perangkat Desa', 'Dalam rangka menuju masyarakat yang adil dan makmur maka pembangunan dilakukan di segala bidang. Pembangunan di bidang kesehatan mempunyai arti yang penting dalam kehidupan nasional, khususnya di dalam memelihara dan meningkatkan kesehatan. Salah satu upaya yang ditempuh melalui kegiatan Pemberdayaan Kader Dalam Rangka Pencegahan Dan Pengendalian Penyakit Menular Dan Tidak Menular, Pelaksanaan Imunisasi Serta Penyehatan Lingkungan. Upaya ini dilaksanakan dengan sumber DAK Non Fisik Puskesmas. Agar kegiatan tersebut terlaksana sesuai dengan acuan, diperlukan kegiatan Pemberdayaan Kader Dalam Rangka Pencegahan Dan Pengendalian Penyakit Menular Dan Tidak Menular, Pelaksanaan Imunisasi Serta Penyehatan Lingkungan Puskesmas Birayang.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1290426);
