INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64052883', 64052883, 'analyze_legacy', 'Kota Palembang', 'kabkota', 'Rumah Sakit Umum Daerah Palembang BARI', 'BELANJA FILM RONTGEN', 'Barang', 'E-Purchasing', 'Sumatera Selatan, Palembang (Kota)', 475000000, 'January 2026', 'BLUD', 0, 0, '1 KEGIATAN', 'Film rontgen adalah film yang digunakan untuk mencetak hasil rontgen sehingga bisa dibaca hasilnya oleh radiografer. Hasil rontgen merupakan salah satu referensi yang digunakan oleh dokter untuk mendiagnosa penyakit yang diderita pasien. Selain film rontgen, pemeriksaan radiologi juga membutuhkan syringe untuk pelayanan CT Scan.', 'Film rontgen yang digunakan memiliki 2 ukuran yaitu 8 x 10 inchi (rontgen thorax) dan 10 x 12 inchi (CT Scan). Bahan film terbuat dari emulsi film yang berisi perak halida. Syringe untuk pelayanan CT Scan merupakan spuit terbuat dari bahan plastik yang terdapat pada alat injektor berisi cairan kontras untuk pemeriksaan radiologi yang menggunakan media kontras; steril; digunakan sekali pakai.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1290609);
