INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64075203', 64075203, 'analyze_legacy', 'Kab. Sleman', 'kabkota', 'DINAS PENDIDIKAN', 'Biaya Pemeliharaan Personal Computer/Notebook', 'Jasa Lainnya', 'E-Purchasing', 'DI Yogyakarta, Sleman (Kab.)', 2190000, 'January 2026', 'APBD', 1, 1, '3 Unit', 'Kegiatan ini mencakup pelaksanaan perawatan preventif dan perbaikan korektif secara berkala terhadap berbagai peralatan kerja serta mesin penunjang kantor guna menjamin kesiapan operasional setiap saat. Lingkup pekerjaan meliputi inspeksi teknis, pembersihan komponen internal, penyetelan ulang sistem, hingga penggantian suku cadang yang telah mencapai batas usia pakai, guna mencegah kerusakan fatal serta memastikan seluruh aset mesin memiliki kinerja yang optimal dan efisien dalam jangka panjang.', 'Pelaksanaan pemeliharaan wajib dilakukan oleh tenaga teknis yang kompeten dengan menggunakan peralatan kerja berstandar teknis yang sesuai. Spesifikasi pekerjaan menekankan pada penggunaan suku cadang asli (original equipment manufacturer) atau yang setara secara kualitas, serta penggunaan bahan pembersih dan pelumas khusus yang tidak merusak komponen mesin. Hasil akhir pekerjaan harus memenuhi standar keamanan operasional, tidak menimbulkan kebisingan yang berlebih, serta memiliki jaminan purnakerja (garansi perbaikan) untuk memastikan keandalan fungsi mesin.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1293008);
