INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64075234', 64075234, 'analyze_legacy', 'Kab. Sleman', 'kabkota', 'DINAS PENDIDIKAN', 'Pemeliharaan Meubelair kantor', 'Jasa Lainnya', 'E-Purchasing', 'DI Yogyakarta, Sleman (Kab.)', 3000000, 'January 2026', 'APBD', 1, 1, '2 Paket', 'Kegiatan ini meliputi rangkaian perawatan rutin dan perbaikan kerusakan pada aset mebel kantor guna mempertahankan fungsi serta estetika sarana kerja. Lingkup pekerjaan mencakup pemeriksaan fisik secara berkala, perbaikan struktur yang longgar atau patah, pelapisan ulang permukaan (refinishing), hingga penggantian suku cadang kecil yang aus, guna memastikan seluruh furnitur tetap aman digunakan dan memiliki masa pakai yang lebih panjang untuk mendukung operasional kantor.', 'Proses pemeliharaan harus menggunakan material perbaikan yang setara atau lebih baik dari kualitas aslinya, termasuk penggunaan bahan perekat, baut, dan pelapis (vernis/kain/kulit sintetis) yang tahan lama serta ramah lingkungan. Spesifikasi teknis mewajibkan hasil pengerjaan yang rapi, presisi, dan ergonomis, di mana setiap mebel yang telah diperbaiki harus kembali stabil secara struktural dan bersih dari noda kimia, sesuai dengan standar kenyamanan ruang kerja perkantoran.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1293531);
