INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64076080', 64076080, 'analyze_legacy', 'Kementerian Energi Dan Sumber Daya Mineral', 'central', 'SEKRETARIAT JENDERAL KEMENTERIAN ENERGI DAN SUMBER DAYA MINERAL', 'Expose Media Digital', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 400000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '2 Paket', 'Kementerian Energi dan Sumber Daya Mineral (ESDM) memiliki peran strategis dalam mengelola, mengatur, dan mengawasi sektor energi dan sumber daya mineral yang menjadi salah satu penopang utama pembangunan nasional. Seiring perkembangan teknologi informasi, pola komunikasi publik juga mengalami perubahan signifikan. Masyarakat kini lebih banyak mengakses informasi melalui media sosial, yang bersifat real-time, interaktif, dan dapat menjangkau berbagai lapisan secara luas. Ekspose Media Digital menjadi sarana untuk menempatkan konten-konten strategis Kementerian ESDM di kanal-kanal digital yang memiliki jangkauan luas dan relevan dengan target audience. Dengan strategi ini, diharapkan informasi dapat diterima secara cepat, meningkatkan literasi publik terkait isu energi dan mineral, serta memperkuat citra Kementerian ESDM sebagai lembaga yang terbuka, informatif, dan responsif terhadap kebutuhan masyarakat.', '1. Meningkatkan jangkauan informasi terkait program, kebijakan, dan capaian Kementerian ESDM kepada masyarakat luas melalui media digital. 2. Membangun dan memperkuat citra Kementerian ESDM sebagai lembaga yang transparan, akuntabel, dan adaptif terhadap perkembangan teknologi komunikasi digital. 3. Mendorong partisipasi dan keterlibatan publik dalam mendukung kebijakan energi dan sumber daya mineral yang berkelanjutan. 4. Meningkatkan literasi masyarakat mengenai isu-isu strategis di sektor energi, mineral, ketenagalistrikan, dan energi terbarukan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1293812);
