INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64075287', 64075287, 'analyze_legacy', 'Kab. Sleman', 'kabkota', 'DINAS PENDIDIKAN', 'Sorting Box PAUD', 'Barang', 'E-Purchasing', 'DI Yogyakarta, Sleman (Kab.)', 3460000, 'January 2026', 'APBD', 1, 1, '20 Set', 'Kegiatan ini meliputi identifikasi kebutuhan, pengadaan, serta distribusi peralatan kerja dan perlengkapan kantor guna memastikan ketersediaan sarana pendukung tugas kedinasan yang memadai. Selain itu, pekerjaan ini mencakup penatausahaan aset secara sistematis dan pemeliharaan fungsionalitas barang agar seluruh unit kerja dapat beroperasi secara efektif, efisien, dan profesional.', 'Peralatan dan perlengkapan kantor yang disediakan harus memiliki standar kualitas tinggi, desain ergonomis, serta fungsionalitas yang sesuai dengan kebutuhan ruang kerja modern untuk mendukung produktivitas pegawai. Spesifikasi teknis menekankan pada penggunaan material yang tahan lama (durabilitas tinggi), memiliki garansi purnajual yang jelas, serta memenuhi unsur estetika dan efisiensi ruang guna menciptakan lingkungan kerja yang tertata dan profesional.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1294377);
