INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64075218', 64075218, 'analyze_legacy', 'Kab. Sleman', 'kabkota', 'DINAS PENDIDIKAN', 'MCB 50A', 'Barang', 'E-Purchasing', 'DI Yogyakarta, Sleman (Kab.)', 592000, 'January 2026', 'APBD', 1, 1, '2 Buah', 'Kegiatan ini meliputi perencanaan kebutuhan, pengadaan, dan penggantian komponen instalasi listrik guna memastikan seluruh sistem penerangan dan kelistrikan gedung berfungsi secara aman dan berkelanjutan. Selain itu, tugas ini mencakup pemeriksaan berkala terhadap panel listrik serta pengelolaan stok suku cadang untuk mendukung kelancaran operasional dan kenyamanan lingkungan kerja di kantor.', 'Komponen instalasi listrik yang disediakan harus memenuhi standar SNI (Standar Nasional Indonesia) dan memiliki label LMK (Lembaga Masalah Kelistrikan) untuk menjamin keamanan dari risiko arus pendek atau kebakaran. Spesifikasi teknis difokuskan pada penggunaan lampu hemat energi (LED) yang ramah lingkungan serta material kabel dan stop kontak berkualitas tinggi yang memiliki daya tahan beban sesuai dengan kapasitas daya bangunan kantor.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1294839);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64076339', 64076339, 'analyze_legacy', 'Kab. Pringsewu', 'kabkota', 'Puskesmas Rejosari', 'Belanja Tagihan Air / PDAM, Puskesmas Rejosari', 'Jasa Lainnya', 'Dikecualikan', 'Lampung, Pringsewu (Kab.)', 6000000, 'January 2026', 'BLUD', 1, 1, '1 tahun', 'Pembayaran Tagihan Air/PDAM', 'Tagihan Air PDAM', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1294840);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64075236', 64075236, 'analyze_legacy', 'Kab. Sleman', 'kabkota', 'DINAS PENDIDIKAN', 'Biaya pemeliharaan gedung tidak bertingkat', 'Pekerjaan Konstruksi', 'E-Purchasing', 'DI Yogyakarta, Sleman (Kab.)', 19400000, 'January 2026', 'APBD', 1, 1, '200 M2', 'Kegiatan ini meliputi pelaksanaan perawatan rutin, perbaikan kerusakan ringan hingga sedang, serta rehabilitasi fisik bangunan guna menjaga keandalan struktur dan fungsi gedung kantor secara berkelanjutan. Lingkup pekerjaan mencakup perbaikan arsitektural, pengecatan ulang, perbaikan sistem sanitasi dan atap yang bocor, serta pemeliharaan area fasad gedung demi memastikan keamanan, kenyamanan, dan keselamatan lingkungan kerja bagi seluruh penghuni bangunan.', 'Pekerjaan rehabilitasi harus menggunakan material bangunan yang memenuhi standar SNI dan memiliki kesesuaian estetika dengan desain eksisting guna menjaga keselarasan visual bangunan. Spesifikasi teknis mewajibkan penerapan standar keselamatan kerja yang ketat (K3), penggunaan bahan bangunan yang tahan cuaca (durabilitas tinggi), serta hasil akhir pengerjaan yang rapi dan presisi untuk menjamin integritas struktural bangunan sesuai dengan peraturan teknis bangunan gedung negara yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1294841);
