INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64075233', 64075233, 'analyze_legacy', 'Kab. Sleman', 'kabkota', 'DINAS PENDIDIKAN', 'Fotocopy', 'Jasa Lainnya', 'E-Purchasing', 'DI Yogyakarta, Sleman (Kab.)', 6470000, 'January 2026', 'APBD', 1, 1, '16175 Lembar', 'Kegiatan ini meliputi pengelolaan proses produksi barang cetakan dan jasa penggandaan dokumen untuk memenuhi kebutuhan administrasi, pelaporan, serta media informasi unit kerja. Lingkup pekerjaan mencakup koordinasi desain tata letak, pemilihan teknik cetak yang efisien, serta pengawasan hasil penggandaan guna memastikan seluruh dokumen negara atau materi publikasi terdistribusi dengan kualitas yang seragam dan tepat waktu.', 'Hasil cetakan dan penggandaan harus memenuhi standar ketajaman resolusi tinggi, akurasi warna yang presisi, serta kerapian dalam proses penjilidan dan pemotongan (finishing). Spesifikasi teknis mewajibkan penggunaan material kertas dengan gramatur yang sesuai standar kearsipan, penggunaan tinta berkualitas yang tidak mudah luntur, serta kepastian kerahasiaan data pada setiap dokumen yang diproduksi sesuai dengan kebijakan keamanan informasi instansi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1295364);
