INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64075200', 64075200, 'analyze_legacy', 'Kab. Sleman', 'kabkota', 'DINAS PENDIDIKAN', 'Biaya pemeliharaan gedung bertingkat', 'Pekerjaan Konstruksi', 'E-Purchasing', 'DI Yogyakarta, Sleman (Kab.)', 16800000, 'January 2026', 'APBD', 1, 1, '100 M2', 'Kegiatan ini meliputi pelaksanaan perawatan rutin, perbaikan kerusakan ringan hingga sedang, serta rehabilitasi fisik bangunan guna menjaga keandalan struktur dan fungsi gedung kantor secara berkelanjutan. Lingkup pekerjaan mencakup perbaikan arsitektural, pengecatan ulang, perbaikan sistem sanitasi dan atap yang bocor, serta pemeliharaan area fasad gedung demi memastikan keamanan, kenyamanan, dan keselamatan lingkungan kerja bagi seluruh penghuni bangunan.', 'Pekerjaan rehabilitasi harus menggunakan material bangunan yang memenuhi standar SNI dan memiliki kesesuaian estetika dengan desain eksisting guna menjaga keselarasan visual bangunan. Spesifikasi teknis mewajibkan penerapan standar keselamatan kerja yang ketat (K3), penggunaan bahan bangunan yang tahan cuaca (durabilitas tinggi), serta hasil akhir pengerjaan yang rapi dan presisi untuk menjamin integritas struktural bangunan sesuai dengan peraturan teknis bangunan gedung negara yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1295788);
