INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64075191', 64075191, 'analyze_legacy', 'Kab. Sleman', 'kabkota', 'DINAS PENDIDIKAN', 'Tisu Besar 250 sheet', 'Barang', 'E-Purchasing', 'DI Yogyakarta, Sleman (Kab.)', 1100000, 'January 2026', 'APBD', 1, 1, '50 Buah', 'Kegiatan ini mencakup perencanaan kebutuhan serta pengadaan bahan dan alat kebersihan kantor guna menjamin ketersediaan logistik operasional yang memadai. Selain itu, tugas ini meliputi penatausahaan stok dan distribusi barang secara akuntabel untuk mendukung terciptanya lingkungan kerja yang bersih, sehat, dan representatif bagi seluruh pegawai.', 'Penyediaan bahan dan alat kebersihan harus memenuhi standar kualitas industri yang ramah lingkungan, efektif membasmi kuman, serta memiliki masa kedaluwarsa minimal dua tahun sejak tanggal pengiriman. Spesifikasi ini juga mewajibkan penyediaan peralatan kerja yang ergonomis dan tahan lama guna mendukung produktivitas petugas kebersihan dalam menjaga sanitasi seluruh area kantor secara optimal.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1297678);
