INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64014271', 64014271, 'analyze_legacy', 'Kementerian Lingkungan Hidup/Badan Pengendalian Lingkungan Hidup', 'central', 'SEKRETARIAT UTAMA KEMENTERIAN LINGKUNGAN HIDUP BPLH', 'Pengadaan Penyedia Jasa Tenaga Kesehatan (Paramedis) In House Clinic KLH/BPLH Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 786000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pengadaan Penyedia Jasa Tenaga Kesehatan (Paramedis) In House Clinic KLH/BPLH berupa 2 Perawat (umum dan gigi) dan 2 dokter (umum dan gigi) termasuk perlengkapannya. Ruang lingkup pekerjaan adalah 1. Layanan Pertolongan Pertama Kedaruratan. 2. Pemberian Resep dari Dokter 3. Pemeriksaan kesehatan sederhana berupa pemeriksaan kolesterol, gula darah dan asam urat 4. Konsultasi kesehatan 5. Layanan pemeriksaan kesehatan rutin pimpinan tinggi KLH/BPLH 6. Dukungan kegiatan/aktifitas KLH/BPLH yang membutuhkan layanan tenaga kesehatan.', '1. Melakukan pengoperasian Klinik KLH/BPLH sesuai standar minimal persyaratan sebuah klinik beroperasi di Lingkungan Perkantoran; 2. Memberikan pelayanan kesehatan yang optimal bagi seluruh Pegawai di Lingkungan KLH/BPLH (Aparatur Sipil Negara/ASN dan Non-ASN), yang terdiri atas: a. Layanan Pertolongan Pertama Kedaruratan. b. Pemberian Resep dari Dokter c. Pemeriksaan kesehatan sederhana berupa pemeriksaan kolesterol, gula darah dan asam urat, dan gigi d. Konsultasi kesehatan e. Layanan pemeriksaan kesehatan rutin pimpinan tinggi KLH/BPLH f. Dukungan kegiatan/aktifitas KLH/BPLH yang membutuhkan layanan tenaga kesehatan. 3. Memberikan penyediaan Sistem Pengelolaan Data Pengunjung Klinik KLH/BPLH; 4. Mendorong untuk terciptanya lingkungan kerja yang sehat di Lingkungan KLH/BPLH; 5. Membuat pelaporan atas kunjungan kesehatan Pegawai KLH/BPLH; 6. Memberikan pendampingan atas kebutuhan dokumentasi keseluruhan kegiatan baik untuk pemeriksaan, pelaporan maupun penyiapan data atas kebutuhan informasi dan pihak-pihak yang berkepentingan; dan 7. Memberikan edukasi kesehatan untuk membuka wawasan kesehatan Pegawai dilingkungan KLH/BPLH', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1297983);
